"""A wrapper over a list of QSslErrors."""

import html
from typing import Sequence

from qutebrowser.qt.network import QSslError

from qutebrowser.utils import usertypes, utils, debug


class CertificateErrorWrapper(usertypes.AbstractCertificateErrorWrapper):

    """A wrapper over a list of QSslErrors."""

    def __init__(self, reply=None, errors: Sequence[QSslError] = None) -> None:
        """Create a wrapper for errors, optionally associated with a reply.

        ``reply`` is accepted for API consistency with the network error
        callback. It is deliberately not queried here; constructing the wrapper
        must not trigger any network operations. The one-argument form remains
        supported for callers which only have the error list.
        """
        if errors is None:
            errors = () if reply is None else reply
        super().__init__()
        self._errors = tuple(errors)  # needs to be hashable

    def __str__(self) -> str:
        return '\n'.join(err.errorString() for err in self._errors)

    def __repr__(self) -> str:
        return utils.get_repr(
            self,
            errors=[debug.qenum_key(QSslError, err.error()) for err in self._errors],
            string=str(self))

    def __hash__(self) -> int:
        return hash(self._errors)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, CertificateErrorWrapper):
            return NotImplemented
        return self._errors == other._errors

    def is_overridable(self) -> bool:
        return True

    def html(self):
        if len(self._errors) == 1:
            return super().html()

        errors = '\n'.join(
            '<li>{}</li>'.format(html.escape(err.errorString()))
            for err in self._errors)
        return '<ul>\n{}\n</ul>'.format(errors)
